async function api(path,body){const options={credentials:'same-origin',headers:{}};if(body!==undefined){options.method='POST';options.headers={'content-type':'application/json','idempotency-key':crypto.randomUUID()};options.body=JSON.stringify(body);}const r=await fetch('/api/payroll/'+path,options);if(!r.ok){let e;try{e=await r.json()}catch{}throw Error(e?.error||'NADI could not complete the request.');}return r.headers.get('content-type')?.includes('application/json')?r.json():r;}
async function confirmAction(path,resource,label,body){const dialog=$('#confirm-dialog'),form=$('#confirm-form');$('#confirm-title').textContent=label;$('#confirm-password').value='';$('#confirm-error').textContent='';const decision=path.endsWith('/approve');$('#confirm-note-label').hidden=!decision;$('#confirm-note').required=decision;$('#confirm-note').value='';return new Promise((resolve,reject)=>{let running=false;const finish=(value,error)=>{form.onsubmit=null;$('#confirm-cancel').onclick=null;dialog.oncancel=null;dialog.close();$('#confirm-password').value='';error?reject(error):resolve(value);};$('#confirm-cancel').onclick=()=>finish(null,Error('Action cancelled.'));dialog.oncancel=e=>{e.preventDefault();finish(null,Error('Action cancelled.'));};form.onsubmit=async e=>{e.preventDefault();if(running)return;running=true;const button=form.querySelector('[type=submit]');button.disabled=true;try{const r=await api('step-up',{password:$('#confirm-password').value,action:'/api/payroll/'+path,resource:String(resource)});if(decision)body.note=$('#confirm-note').value;finish(r.challenge);}catch(e){$('#confirm-error').textContent=e.message;}finally{running=false;button.disabled=false;}};dialog.showModal();$('#confirm-password').focus();});}
